/* Internal implementation of mq_setattr/mq_getattr */
struct mq_attr {
    long mq_flags;      /* O_NONBLOCK, etc. */
    long mq_maxmsg;
    long mq_msgsize;
    long mq_curmsgs;    /* Read-only status */
};

mqd_t mqdes;
struct mq_attr current_attr, old_attr;

/* Prepare new attributes (e.g., set non-blocking flag) */
current_attr.mq_flags = O_NONBLOCK;

/* Set new attributes and store the previous state in old_attr */
int status = mq_getsetattr(mqdes, &current_attr, &old_attr);

/* Retrieve current attributes only (newattr must be NULL) */
mq_getsetattr(mqdes, NULL, &current_attr);

/* Error check */
if (status == -1) { /* errno is set */ }
